import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import "../css/homepage.css";
import "../css/review.css";

const USER_KEY = "user";
const TOKEN_KEY = "token";

const API_BASE_URL = "http://localhost:5001";
const PAGE_SIZE = 6;

const state = {
  rooms: [],
  reviews: [],
  selectedRoomId: "",
  rating: 0,
  visibleCount: PAGE_SIZE,
  user: null,
  token: ""
};

const $ = (id) => document.getElementById(id);

document.addEventListener("DOMContentLoaded", init);

async function init() {
  readSession();
  bindEvents();
  renderProfile();
  await loadRooms();

  if (state.selectedRoomId) {
    await loadRoomData();
  }
}

function readSession() {
  try {
    state.user = JSON.parse(localStorage.getItem("user") || "null");
  } catch {
    state.user = null;
  }

  state.token = localStorage.getItem("token") || "";
}

function bindEvents() {
  $("roomSelect").addEventListener("change", async (event) => {
    state.selectedRoomId = event.target.value;
    $("formRoomSelect").value = state.selectedRoomId;
    state.visibleCount = PAGE_SIZE;
    await loadRoomData();
  });

  $("refreshButton").addEventListener("click", async () => {
    await loadRooms();
    await loadRoomData();
  });

  $("searchInput").addEventListener("input", () => {
    state.visibleCount = PAGE_SIZE;
    renderReviews();
  });

  $("ratingFilter").addEventListener("change", () => {
    state.visibleCount = PAGE_SIZE;
    renderReviews();
  });

  $("sortSelect").addEventListener("change", () => {
    state.visibleCount = PAGE_SIZE;
    renderReviews();
  });

  $("loadMoreButton").addEventListener("click", () => {
    state.visibleCount += PAGE_SIZE;
    renderReviews();
  });

  $("openReviewButton").addEventListener("click", () => {
    openModal("review");
  });

  $("openFeedbackButton").addEventListener("click", () => {
    openModal("suggestion");
  });

  $("closeModalButton").addEventListener("click", closeModal);

  $("reviewModal").addEventListener("click", (event) => {
    if (event.target === $("reviewModal")) closeModal();
  });

  $("feedbackType").addEventListener("change", updateRatingVisibility);

  $("ratingInput").querySelectorAll("[data-rating]").forEach((button) => {
    button.addEventListener("click", () => {
      setRating(Number(button.dataset.rating));
    });
  });

  $("reviewForm").addEventListener("submit", submitReview);

  $("profileButton").addEventListener("click", () => {
    const menu = $("profileMenu");
    const willOpen = menu.classList.contains("hidden");

    menu.classList.toggle("hidden", !willOpen);
    $("profileButton").setAttribute("aria-expanded", String(willOpen));
  });

  document.addEventListener("click", (event) => {
    if (
      !event.target.closest(".profile-button") &&
      !event.target.closest(".profile-menu")
    ) {
      $("profileMenu").classList.add("hidden");
      $("profileButton").setAttribute("aria-expanded", "false");
    }
  });

  $("logoutButton").addEventListener("click", () => {
    localStorage.removeItem("user");
    localStorage.removeItem("token");
    window.location.href = "/";
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") closeModal();
  });
}

function renderProfile() {
  const user = state.user || {};

  const name =
    user.displayname_th ||
    user.displayname_en ||
    user.username ||
    "PROFILE";

  $("profileName").textContent =
    name === "PROFILE" ? "PROFILE" : name;

  $("profileFullName").textContent = name;
  $("profileEmail").textContent = user.email || "";
  $("profileAvatar").textContent =
    String(name).trim().charAt(0).toUpperCase() || "U";
}

function authHeaders(includeJson = false) {
  const headers = {};

  if (includeJson) {
    headers["Content-Type"] = "application/json";
  }

  if (state.token) {
    headers.Authorization = `Bearer ${state.token}`;
  }

  const userId = state.user?.user_id ?? state.user?.id;

  if (userId != null) {
    headers["x-user-id"] = String(userId);
  }

  return headers;
}

async function apiFetch(path, options = {}) {
  const response = await fetch(`${API_BASE_URL}${path}`, {
    ...options,
    headers: {
      ...authHeaders(Boolean(options.body)),
      ...(options.headers || {})
    }
  });

  const contentType = response.headers.get("content-type") || "";

  const payload = contentType.includes("application/json")
    ? await response.json()
    : await response.text();

  if (!response.ok) {
    throw new Error(
      payload?.message || `Request failed (${response.status})`
    );
  }

  return payload;
}

async function loadRooms() {
  setStatus("กำลังโหลดรายชื่อห้อง...", true);

  try {
    const payload = await apiFetch("/api/rooms");

    const rooms = Array.isArray(payload)
      ? payload
      : payload.rooms || payload.data || [];

    state.rooms = rooms
      .map(normalizeRoom)
      .filter((room) => room.id !== "");

    fillRoomSelects();

    if (
      !state.selectedRoomId ||
      !state.rooms.some((room) => room.id === state.selectedRoomId)
    ) {
      state.selectedRoomId = state.rooms[0]?.id || "";
    }

    $("roomSelect").value = state.selectedRoomId;
    $("formRoomSelect").value = state.selectedRoomId;

    if (state.rooms.length) {
      setStatus("", false);
    } else {
      setStatus("ไม่พบข้อมูลห้องจาก API /api/rooms", true);
    }
  } catch (error) {
    state.rooms = [];
    fillRoomSelects();

    setStatus(
      `โหลดรายชื่อห้องไม่สำเร็จ: ${error.message} — ตรวจสอบ Backend และ GET /api/rooms`,
      true
    );
  }
}

function normalizeRoom(room) {
  const id = room.room_id ?? room.id ?? room.id_room ?? "";

  const name =
    room.room_name ??
    room.name ??
    room.roomName ??
    `ห้อง ${id}`;

  const number = room.room_number ?? room.room_no ?? "";

  const label =
    number && !String(name).includes(String(number))
      ? `${number} ${name}`
      : name;

  return {
    id: String(id),
    name: String(label)
  };
}

function fillRoomSelects() {
  const selects = [$("roomSelect"), $("formRoomSelect")];

  selects.forEach((select) => {
    const previousValue = select.value;

    select.innerHTML = "";

    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = state.rooms.length
      ? "เลือกห้อง"
      : "ไม่มีข้อมูลห้อง";

    select.appendChild(placeholder);

    state.rooms.forEach((room) => {
      const option = document.createElement("option");
      option.value = room.id;
      option.textContent = room.name;
      select.appendChild(option);
    });

    if (state.rooms.some((room) => room.id === previousValue)) {
      select.value = previousValue;
    }
  });
}

async function loadRoomData() {
  const roomId = state.selectedRoomId;

  if (!roomId) {
    state.reviews = [];
    renderStats([], null);
    renderReviews();

    $("reviewsRoomLabel").textContent = "เลือกห้องเพื่อดูรีวิว";
    $("usageCount").textContent = "—";
    return;
  }

  const room = state.rooms.find((item) => item.id === roomId);

  $("reviewsRoomLabel").textContent = room
    ? `รีวิวของ ${room.name}`
    : "รีวิวของห้องที่เลือก";

  $("roomHelp").textContent = room
    ? `กำลังแสดงข้อมูลของ ${room.name}`
    : "คะแนนและรีวิวจะแสดงตามห้องที่เลือก";

  setStatus("กำลังโหลดรีวิวและสถิติห้อง...", true);

  const [reviewResult, usageResult] = await Promise.allSettled([
    apiFetch(`/api/reviews?room_id=${encodeURIComponent(roomId)}`),
    apiFetch(`/api/rooms/usage?room_id=${encodeURIComponent(roomId)}`)
  ]);

  if (reviewResult.status === "fulfilled") {
    const payload = reviewResult.value;

    const reviews = Array.isArray(payload)
      ? payload
      : payload.reviews || payload.data || [];

    state.reviews = reviews.map(normalizeReview);
  } else {
    state.reviews = [];
  }

  const usage =
    usageResult.status === "fulfilled"
      ? extractUsage(usageResult.value)
      : null;

  renderStats(state.reviews, usage);
  renderReviews();

  const errors = [];

  if (reviewResult.status === "rejected") {
    errors.push(`โหลดรีวิวไม่สำเร็จ: ${reviewResult.reason.message}`);
  }

  if (usageResult.status === "rejected") {
    errors.push(`โหลดสถิติการใช้งานไม่สำเร็จ: ${usageResult.reason.message}`);
  }

  setStatus(
    errors.length
      ? `${errors.join(" | ")} — ตรวจสอบ API ใน Backend`
      : "",
    errors.length > 0
  );
}

function normalizeReview(review) {
  return {
    id: review.review_id ?? review.id ?? "",
    roomId: String(review.room_id ?? ""),
    name:
      review.displayname_th ||
      review.displayname_en ||
      review.username ||
      review.name ||
      "ผู้ใช้งาน",
    date: review.created_at || review.date || "",
    rating: Number(review.rating || 0),
    message: review.comment ?? review.message ?? "",
    type: review.feedback_type || review.type || "review"
  };
}

function extractUsage(payload) {
  if (typeof payload === "number") return payload;

  if (typeof payload === "string" && payload.trim() !== "") {
    return Number(payload);
  }

  return Number(
    payload?.usage_count ??
    payload?.count ??
    payload?.total ??
    payload?.data?.usage_count ??
    0
  );
}

function renderStats(reviews, usage) {
  const validRatings = reviews.filter(
    (review) => review.rating >= 1 && review.rating <= 5
  );

  const average = validRatings.length
    ? validRatings.reduce((sum, review) => sum + review.rating, 0) /
      validRatings.length
    : null;

  $("averageRating").textContent =
    average === null ? "—" : average.toFixed(1);

  $("averageStars").textContent =
    average === null
      ? "☆☆☆☆☆"
      : "★".repeat(Math.round(average)) +
        "☆".repeat(5 - Math.round(average));

  $("reviewCountText").textContent =
    `${validRatings.length.toLocaleString("th-TH")} รีวิวที่มีคะแนน`;

  $("usageCount").textContent =
    usage === null || !Number.isFinite(usage)
      ? "—"
      : Math.max(0, usage).toLocaleString("th-TH");
}

function renderReviews() {
  const query = $("searchInput").value.trim().toLowerCase();
  const rating = $("ratingFilter").value;
  const sort = $("sortSelect").value;

  let reviews = state.reviews.filter((review) => {
    const matchesQuery =
      `${review.name} ${review.message}`.toLowerCase().includes(query);

    const matchesRating =
      rating === "all" || String(review.rating) === rating;

    return matchesQuery && matchesRating;
  });

  reviews.sort((a, b) => {
    const dateA = new Date(a.date || 0).getTime();
    const dateB = new Date(b.date || 0).getTime();

    if (sort === "highest") {
      return b.rating - a.rating || dateB - dateA;
    }

    if (sort === "lowest") {
      return a.rating - b.rating || dateB - dateA;
    }

    return dateB - dateA;
  });

  const visible = reviews.slice(0, state.visibleCount);
  const list = $("reviewsList");

  list.innerHTML = "";

  if (!visible.length) {
    const empty = document.createElement("div");
    empty.className = "empty-state";
    empty.textContent = state.selectedRoomId
      ? "ยังไม่มีรีวิวที่ตรงกับเงื่อนไขนี้ ลองเปลี่ยนตัวกรองหรือเขียนรีวิวห้องนี้"
      : "กรุณาเลือกห้องเพื่อดูรีวิว";

    list.appendChild(empty);
  } else {
    visible.forEach((review) => {
      list.appendChild(createReviewCard(review));
    });
  }

  $("loadMoreButton").classList.toggle(
    "hidden",
    reviews.length <= visible.length
  );
}

function createReviewCard(review) {
  const card = document.createElement("article");
  card.className = "review-card";

  const top = document.createElement("div");
  top.className = "review-top";

  const reviewer = document.createElement("div");
  reviewer.className = "reviewer";

  const avatar = document.createElement("div");
  avatar.className = "reviewer-avatar";
  avatar.textContent = review.name.trim().charAt(0).toUpperCase() || "U";

  const identity = document.createElement("div");

  const name = document.createElement("p");
  name.className = "reviewer-name";
  name.textContent = review.name;

  const date = document.createElement("div");
  date.className = "review-date";
  date.textContent = formatDate(review.date);

  identity.append(name, date);
  reviewer.append(avatar, identity);

  const stars = document.createElement("div");
  stars.className = "review-rating";
  stars.textContent = review.rating
    ? "★".repeat(review.rating) + "☆".repeat(5 - review.rating)
    : "ไม่ให้คะแนน";

  top.append(reviewer, stars);

  const type = document.createElement("span");
  type.className = "review-type";
  type.textContent = typeLabel(review.type);

  const message = document.createElement("p");
  message.className = "review-message";
  message.textContent = review.message || "ไม่มีรายละเอียด";

  card.append(top, type, message);

  return card;
}

function formatDate(value) {
  if (!value) return "ไม่ระบุวันที่";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return String(value);
  }

  return new Intl.DateTimeFormat("th-TH", {
    day: "numeric",
    month: "short",
    year: "numeric"
  }).format(date);
}

function typeLabel(type) {
  const labels = {
    review: "รีวิวการใช้งาน",
    suggestion: "ข้อเสนอแนะ",
    problem: "แจ้งปัญหา"
  };

  return labels[type] || type;
}

function setStatus(message, visible) {
  const box = $("statusMessage");
  box.textContent = message;
  box.classList.toggle("hidden", !visible || !message);
}

function openModal(type) {
  $("reviewModal").classList.remove("hidden");
  $("formRoomSelect").value = state.selectedRoomId;
  $("feedbackType").value = type;
  $("reviewMessage").value = "";
  $("formMessage").textContent = "";
  $("formMessage").classList.remove("success");

  setRating(0);
  updateRatingVisibility();
}

function closeModal() {
  $("reviewModal").classList.add("hidden");
}

function setRating(value) {
  state.rating = value;

  $("ratingInput").querySelectorAll("[data-rating]").forEach((button) => {
    const buttonRating = Number(button.dataset.rating);
    const selected = buttonRating <= value;

    button.classList.toggle("selected", selected);
    button.setAttribute("aria-checked", String(buttonRating === value));
  });

  $("ratingHelp").textContent = value
    ? `คุณให้ ${value} จาก 5 ดาว`
    : "เลือกคะแนน 1–5 ดาว";
}

function updateRatingVisibility() {
  const isReview = $("feedbackType").value === "review";

  $("ratingField").classList.toggle("hidden", !isReview);
}

async function submitReview(event) {
  event.preventDefault();

  const messageBox = $("formMessage");
  messageBox.textContent = "";
  messageBox.classList.remove("success");

  if (!state.user) {
    messageBox.textContent = "กรุณาเข้าสู่ระบบก่อนส่งความคิดเห็น";
    return;
  }

  const roomId = $("formRoomSelect").value;
  const type = $("feedbackType").value;
  const message = $("reviewMessage").value.trim();

  if (!roomId || !message) {
    messageBox.textContent = "กรุณาเลือกห้องและกรอกรายละเอียด";
    return;
  }

  if (type === "review" && !state.rating) {
    messageBox.textContent = "กรุณาเลือกคะแนนรีวิว 1–5 ดาว";
    return;
  }

  const userId = state.user.user_id ?? state.user.id;

  if (userId == null) {
    messageBox.textContent = "ไม่พบรหัสผู้ใช้ กรุณาเข้าสู่ระบบใหม่";
    return;
  }

  const payload = {
    room_id: Number(roomId),
    user_id: userId,
    rating: type === "review" ? state.rating : null,
    feedback_type: type,
    comment: message
  };

  const submitButton = $("submitReviewButton");
  submitButton.disabled = true;
  submitButton.textContent = "กำลังส่ง...";

  try {
    await apiFetch("/api/reviews", {
      method: "POST",
      body: JSON.stringify(payload)
    });

    messageBox.textContent =
      "ส่งความคิดเห็นสำเร็จ ขอบคุณสำหรับข้อเสนอแนะ!";
    messageBox.classList.add("success");

    state.selectedRoomId = roomId;
    $("roomSelect").value = roomId;

    await loadRoomData();

    window.setTimeout(closeModal, 900);
  } catch (error) {
    messageBox.textContent =
      `ส่งความคิดเห็นไม่สำเร็จ: ${error.message} — ตรวจสอบ POST /api/reviews ใน Backend`;
  } finally {
    submitButton.disabled = false;
    submitButton.textContent = "ส่งความคิดเห็น";
  }
}
